package com.alsafa.native4;

import android.app.Activity;
import android.content.ContentValues;
import android.os.Bundle;
import android.view.View;
import android.widget.Button;
import android.widget.EditText;
import android.widget.LinearLayout;
import android.widget.TextView;
import com.alsafa.native4.core.CoreDb;
import com.alsafa.native4.core.DailyClosingStore;
import com.alsafa.native4.sync.OutboxDb;
import com.alsafa.native4.sync.OutboxSender;
import com.alsafa.native4.sync.FirestoreDirectTransport;
import com.google.firebase.auth.FirebaseAuth;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.List;
import java.util.Locale;

/** Native 4 isolated Android shell. Proven Alpha sync remains untouched; closing is migrated incrementally to CoreDb. */
public class MainActivity extends Activity {
 private static final String TEST_STORE="test-native4-android-alpha";
 private TextView status,authStatus,products,sales,repairs,outbox,sectionTitle,sectionSubtitle,saleSelectedProduct,expectedClosing,drawerOut;
 private EditText authEmail,authPassword,productName,productQuantity,productPrice,saleSearch,saleProductId,saleQuantity,salePayment,repairCustomer,repairWatch,repairTotal,repairPayment;
 private EditText closingDay,openingUsd,openingTry,openingSyp,countedUsd,countedTry,countedSyp,carryUsd,carryTry,carrySyp,closingNotes;
 private LinearLayout testPanel,saleSearchResults,closingPanel;
 private OutboxDb db; private CoreDb coreDb; private DailyClosingStore closingStore; private FirebaseAuth auth;
 @Override public void onCreate(Bundle state){
  super.onCreate(state);Native4Safety.requireIsolatedStore(TEST_STORE);setContentView(R.layout.activity_main);db=new OutboxDb(this);recoverMissingDefaultDatabaseFailures();db.recoverInterrupted();coreDb=new CoreDb(this);closingStore=new DailyClosingStore(coreDb,"native4-android-alpha");auth=FirebaseAuth.getInstance();
  status=findViewById(R.id.status);authStatus=findViewById(R.id.authStatus);products=findViewById(R.id.products);sales=findViewById(R.id.sales);repairs=findViewById(R.id.repairs);outbox=findViewById(R.id.outbox);sectionTitle=findViewById(R.id.sectionTitle);sectionSubtitle=findViewById(R.id.sectionSubtitle);testPanel=findViewById(R.id.testPanel);saleSearchResults=findViewById(R.id.saleSearchResults);saleSelectedProduct=findViewById(R.id.saleSelectedProduct);closingPanel=findViewById(R.id.closingPanel);expectedClosing=findViewById(R.id.expectedClosing);drawerOut=findViewById(R.id.drawerOut);
  authEmail=findViewById(R.id.authEmail);authPassword=findViewById(R.id.authPassword);productName=findViewById(R.id.productName);productQuantity=findViewById(R.id.productQuantity);productPrice=findViewById(R.id.productPrice);saleSearch=findViewById(R.id.saleSearch);saleProductId=findViewById(R.id.saleProductId);saleQuantity=findViewById(R.id.saleQuantity);salePayment=findViewById(R.id.salePayment);repairCustomer=findViewById(R.id.repairCustomer);repairWatch=findViewById(R.id.repairWatch);repairTotal=findViewById(R.id.repairTotal);repairPayment=findViewById(R.id.repairPayment);
  closingDay=findViewById(R.id.closingDay);openingUsd=findViewById(R.id.openingUsd);openingTry=findViewById(R.id.openingTry);openingSyp=findViewById(R.id.openingSyp);countedUsd=findViewById(R.id.countedUsd);countedTry=findViewById(R.id.countedTry);countedSyp=findViewById(R.id.countedSyp);carryUsd=findViewById(R.id.carryUsd);carryTry=findViewById(R.id.carryTry);carrySyp=findViewById(R.id.carrySyp);closingNotes=findViewById(R.id.closingNotes);closingDay.setText(new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));
  bindSection(R.id.navSales,HomeSection.SALES);bindSection(R.id.navRepairs,HomeSection.REPAIRS);bindSection(R.id.navProducts,HomeSection.PRODUCTS);bindSection(R.id.navPurchases,HomeSection.PURCHASES);bindSection(R.id.navCash,HomeSection.CASH);bindSection(R.id.navClosing,HomeSection.CLOSING);bindSection(R.id.navReports,HomeSection.REPORTS);bindSection(R.id.navSettings,HomeSection.SETTINGS);
  findViewById(R.id.signIn).setOnClickListener(v->signIn());findViewById(R.id.signOut).setOnClickListener(v->{auth.signOut();authPassword.setText("");status.setText("تم تسجيل الخروج");refresh();});findViewById(R.id.sendOutbox).setOnClickListener(v->sendOutbox());findViewById(R.id.saveProduct).setOnClickListener(v->saveProduct());findViewById(R.id.searchSaleProduct).setOnClickListener(v->searchSaleProducts());findViewById(R.id.saveSale).setOnClickListener(v->saveSale());findViewById(R.id.saveRepair).setOnClickListener(v->saveRepair());findViewById(R.id.openWorkDay).setOnClickListener(v->openWorkDay());findViewById(R.id.refreshExpected).setOnClickListener(v->refreshExpected());findViewById(R.id.calcDrawerOut).setOnClickListener(v->calculateDrawerOut());findViewById(R.id.closeWorkDay).setOnClickListener(v->closeWorkDay());showSection(HomeSection.SALES);refresh();
 }
 private void recoverMissingDefaultDatabaseFailures(){ContentValues v=new ContentValues();v.put("state","FAILED_RETRYABLE");v.put("last_error","تم إنشاء Firestore (default) ونشر القواعد؛ أعيدت العملية القديمة للمحاولة بنفس operationId");db.getWritableDatabase().update("outbox",v,"state='FAILED_PERMANENT' AND last_error LIKE ?",new String[]{"%database (default) does not exist for project alsafa-native%"});}
 private void bindSection(int id,HomeSection section){findViewById(id).setOnClickListener(v->showSection(section));}
 private void showSection(HomeSection section){sectionTitle.setText(section.title);sectionSubtitle.setText(section.subtitle);boolean alpha=section==HomeSection.SALES||section==HomeSection.REPAIRS||section==HomeSection.PRODUCTS;boolean closing=section==HomeSection.CLOSING;testPanel.setVisibility(alpha?View.VISIBLE:View.GONE);closingPanel.setVisibility(closing?View.VISIBLE:View.GONE);status.setText(alpha?"وضع Alpha معزول — الحفظ محلي أولاً ثم Outbox":closing?"الإقفال يعمل على CoreDb المحلي — العملات منفصلة":"هذه الوحدة ضمن بناء v4.1 ولم تُفعّل للكتابة بعد");if(closing)refreshExpectedQuietly();}
 private void signIn(){String email=authEmail.getText().toString().trim();String password=authPassword.getText().toString();if(email.isEmpty()||password.isEmpty()){status.setText("أدخل بريد وكلمة مرور مستخدم الاختبار");return;}status.setText("جاري تسجيل الدخول...");auth.signInWithEmailAndPassword(email,password).addOnCompleteListener(this,t->{authPassword.setText("");status.setText(t.isSuccessful()?"✓ تم تسجيل الدخول إلى Firebase التجريبي":"فشل تسجيل الدخول: "+(t.getException()==null?"خطأ غير معروف":t.getException().getClass().getSimpleName()));refresh();});}
 private void sendOutbox(){Native4Safety.requireIsolatedStore(TEST_STORE);if(auth.getCurrentUser()==null){status.setText("سجل الدخول أولاً؛ لم يتم إرسال شيء");return;}status.setText("جاري إرسال Outbox مباشرة إلى Firebase...");new Thread(()->{try{OutboxSender sender=new OutboxSender(db,new FirestoreDirectTransport(),TEST_STORE);int confirmed=sender.drainOnce();runOnUiThread(()->{status.setText("انتهت محاولة Firebase المباشرة. المؤكد: "+confirmed);refresh();});}catch(Exception e){runOnUiThread(()->{status.setText("تعذر الإرسال: "+e.getClass().getSimpleName());refresh();});}}).start();}
 private void saveProduct(){try{String enteredName=productName.getText().toString().trim();String id=db.addTestProduct(enteredName,Integer.parseInt(productQuantity.getText().toString().trim()),Double.parseDouble(productPrice.getText().toString().trim()));productName.setText("");productQuantity.setText("");productPrice.setText("");List<OutboxDb.ProductHit> hits=db.searchProducts(enteredName,12);for(OutboxDb.ProductHit hit:hits){if(id.equals(hit.id)){selectProduct(hit);break;}}status.setText("✓ المنتج حُفظ محلياً ويمكن استخدامه في المبيع");refresh();}catch(Exception e){status.setText("لم يُحفظ المنتج: "+e.getMessage());}}
 private void searchSaleProducts(){saleSearchResults.removeAllViews();List<OutboxDb.ProductHit> hits=db.searchProducts(saleSearch.getText().toString(),12);if(hits.isEmpty()){TextView empty=new TextView(this);empty.setText("لا توجد نتائج مطابقة");empty.setGravity(View.TEXT_ALIGNMENT_TEXT_END);saleSearchResults.addView(empty);return;}for(OutboxDb.ProductHit hit:hits){Button b=new Button(this);b.setAllCaps(false);b.setText(hit.label());b.setOnClickListener(v->selectProduct(hit));saleSearchResults.addView(b);}}
 private void selectProduct(OutboxDb.ProductHit hit){saleProductId.setText(hit.id);saleSelectedProduct.setText("المحدد: "+hit.label());saleSearch.setText(hit.name);saleSearchResults.removeAllViews();status.setText("✓ تم اختيار المنتج");}
 private void saveSale(){try{OutboxDb.SaleResult r=db.recordTestSale(saleProductId.getText().toString().trim(),Integer.parseInt(saleQuantity.getText().toString().trim()),salePayment.getText().toString());status.setText("✓ ثبتت الفاتورة "+r.invoiceNo+" محلياً مع أمر المزامنة. المتبقي: "+r.remainingQty);saleQuantity.setText("");saleProductId.setText("");saleSelectedProduct.setText("لم يتم اختيار منتج");saleSearch.setText("");saleSearchResults.removeAllViews();refresh();}catch(Exception e){status.setText("لم تُنفذ الفاتورة: "+e.getMessage());}}
 private void saveRepair(){try{OutboxDb.RepairResult r=db.recordTestRepair(repairCustomer.getText().toString(),repairWatch.getText().toString(),Double.parseDouble(repairTotal.getText().toString().trim()),repairPayment.getText().toString());repairCustomer.setText("");repairWatch.setText("");repairTotal.setText("");status.setText("✓ ثبتت صيانة "+r.invoiceNo+" محلياً: "+r.watch);refresh();}catch(Exception e){status.setText("لم تُنفذ الصيانة: "+e.getMessage());}}
 private void openWorkDay(){try{closingStore.open(day(),money(openingUsd),money(openingTry),money(openingSyp),"");status.setText("✓ تم فتح يوم العمل وحفظ المدوّر محلياً + Outbox");refreshExpected();}catch(Exception e){status.setText("لم يُفتح يوم العمل: "+message(e));}}
 private void refreshExpected(){try{DailyClosingStore.Expected e=closingStore.expected(day());expectedClosing.setText("المتوقع — USD: "+fmt(e.usd)+" | TRY: "+fmt(e.tryAmount)+" | SYP: "+fmt(e.syp));status.setText("✓ تم تحديث المتوقع من مدوّر البداية وحركات هذا اليوم فقط");}catch(Exception e){expectedClosing.setText("المتوقع: —");status.setText("تعذر حساب المتوقع: "+message(e));}}
 private void refreshExpectedQuietly(){try{DailyClosingStore.Expected e=closingStore.expected(day());expectedClosing.setText("المتوقع — USD: "+fmt(e.usd)+" | TRY: "+fmt(e.tryAmount)+" | SYP: "+fmt(e.syp));}catch(Exception ignored){expectedClosing.setText("المتوقع: افتح يوم العمل أولاً");}}
 private void calculateDrawerOut(){try{double u=drawer(money(countedUsd),money(carryUsd)),t=drawer(money(countedTry),money(carryTry)),s=drawer(money(countedSyp),money(carrySyp));drawerOut.setText("الخارج من الدرج — USD: "+fmt(u)+" | TRY: "+fmt(t)+" | SYP: "+fmt(s));status.setText("✓ تم الحساب دون تحويل بين العملات");}catch(Exception e){status.setText("تعذر الحساب: "+message(e));}}
 private void closeWorkDay(){try{double cu=money(countedUsd),ct=money(countedTry),cs=money(countedSyp),ku=money(carryUsd),kt=money(carryTry),ks=money(carrySyp);String id=closingStore.close(day(),cu,ct,cs,ku,kt,ks,closingNotes.getText().toString());drawerOut.setText("الخارج من الدرج — USD: "+fmt(drawer(cu,ku))+" | TRY: "+fmt(drawer(ct,kt))+" | SYP: "+fmt(drawer(cs,ks)));status.setText("✓ تم إقفال اليوم محلياً وتثبيت المدوّر. المرجع: "+id);expectedClosing.setText("اليوم مقفل — المدوّر المحفوظ هو فقط ما سيبدأ به اليوم التالي");}catch(Exception e){status.setText("لم يتم الإقفال: "+message(e));}}
 private String day(){return closingDay.getText().toString().trim();}
 private static double money(EditText e){String v=e.getText().toString().trim();return v.isEmpty()?0:Double.parseDouble(v);}
 private static double drawer(double counted,double carry){if(!Double.isFinite(counted)||!Double.isFinite(carry)||counted<0||carry<0||carry>counted)throw new IllegalArgumentException("المدوّر يجب أن يكون بين صفر والمبلغ المعدود");return counted-carry;}
 private static String fmt(double v){return String.format(Locale.US,"%.2f",v);}
 private static String message(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}
 private void refresh(){authStatus.setText(auth.getCurrentUser()==null?"Firebase Auth: غير مسجل":"Firebase Auth: مسجل — "+auth.getCurrentUser().getEmail());products.setText(db.testProductsSummary());sales.setText(db.salesSummary());repairs.setText(db.repairsSummary());outbox.setText("عمليات بانتظار التأكيد: "+db.pendingCount()+"\n\n"+db.outboxSummary());}
}
